import { mileReceiverFeedback, MILE_RECEIVER_GUIDANCE } from './hundredHandMileReceiverFeedback.js';
import { getPromptDeck } from './promptDeck.js';
const ID='hundred-hand-mile:restoration';
const MILESTONES={survey:'Break surveyed.',recover_power:'Recovered power installed.',restore_guide:'Route guide installed.',deliver_cargo:'Cargo contribution installed.',witness_convoy:'First convoy crossing witnessed.'};
const REFUSALS={
 'source-outside-receiver':'Tow the whole original part into the service capture beside its matching socket.',
 'receiver-speed-too-high':'Slow the part and let its rotation settle inside the socket.',
 'current-native-player-tow-required':'Keep your live Massline attached to the original part.',
 'hold-outside-service-receiver':'Bring your ship close to the service socket and slow to a stop.',
 'unreserved-cargo-required':'Free the required goods in your hold; reserved cargo cannot be contributed.',
 'installation-volume-occupied':'Move ships and loose objects clear of the installation socket.',
 'installation-volume-occupied-or-unknown':'Clear the socket and wait for the physical clearance check.',
 'installation-pending':'Your contribution is committed. Keep the socket clear while it is installed.',
 'stale-revision':'The work order changed. Scan the site again before contributing.',
 'spawn-budget-full':'Traffic is at capacity. Keep flying nearby and request the convoy again shortly.',
 'current-navigability-proof-required':'The route is occupied or its clearance is still being checked.',
 'native-route-changed':'Something entered the route. Clear it before requesting the convoy again.',
 'finite-original-source-unavailable':'The original part is unavailable. No duplicate can be supplied.',
 'two-verified-interventions-required':'The crew record changed. Scan the Mile again to check the work order.',
};
const WORK_FAMILIES = Object.freeze({
 tally: { name: 'Tally Three delivery', action: 'Ceres: tow Tally Three’s original crate on your live Massline to Ceres Refinery; slow the crate to 8 WU/s or less, hail and choose DELIVER' },
 ilex: { name: 'Ilex Ark settlement', action: 'finish the Ilex Ark run (any recorded outcome)' },
 towline: { name: 'Towline Table cleanup', action: 'finish one Towline Table cleanup' },
 lastShift: { name: 'Last Shift archive report', action: 'Ceres: select a marked Last Shift wreck, pulse scan within 320 WU, then choose FILE 1/3 SOURCES; a partial report counts' },
});
function prerequisiteGuidance(row) {
 const raw = row.evidence?.families;
 // This is a view of the graph's verified families, never a second receipt validator.
 // Unknown/missing data asks for a fresh owner readout, not invented remaining work.
 if (!Array.isArray(raw) || Array.from(raw).some(id => typeof id !== 'string' || !Object.hasOwn(WORK_FAMILIES, id)))
  return 'The crew record needs refreshing. Scan the Mile again to check your work order.';
 const families = [...new Set(raw)];
 const progress = `Recorded: ${families.length <= 2 ? families.length + " of 2 kinds of work" : families.length + " kinds of work (2 required)"}${families.length ? ': ' + families.map(id => WORK_FAMILIES[id].name).join(', ') : ''}.`;
 if (row.lastResult?.ok === false && ['stale-revision', 'two-verified-interventions-required', 'site-unavailable', 'current-site-inspection-required'].includes(row.lastResult.reason))
  return progress + ' Scan the Mile again to refresh the work order.';
 if (families.length >= 2)
  return progress + (row.canAccept ? ' Restore a short working route with recovered parts. Earlier deliveries stay spent.' : ' Return to the Mile and scan again to check the work order.');
 if (row.canAccept) return 'The crew record needs refreshing. Scan the Mile again to check your work order.';
 const remaining = Object.keys(WORK_FAMILIES).filter(id => !families.includes(id)).map(id => WORK_FAMILIES[id].action);
 return progress + (families.length ? ' Choose one other kind of work: ' : ' Any two count: ') + remaining.join('; ') + '.';
}
const LABELS={power:'INSTALL RECOVERED POWER',guide:'INSTALL RECOVERED GUIDE',cargo:'CONTRIBUTE CARGO'};
export const hundredHandMilePrompt={
 name:'hundredHandMilePrompt',
 init(ctx){for(const off of this._subs||[])off?.();this.state=ctx.state;this.bus=ctx.bus;this._active=null;this._epoch=(this._epoch||0)+1;this._destroyed=false;this._subs=[ctx.bus.on('hundredHandMile:offer',r=>this.offer(r)),ctx.bus.on('hundredHandMile:milestone',r=>{
  const text=MILESTONES[r?.chapterId];if(text)this.bus.emit('toast',{text:'Hundred-Hand Mile: '+text,kind:'info',ttl:6});
 })];
  for(const event of ['sector:exit','dock:completed','dock:docked','save:restoring','save:loaded','game:load','game:new','game:newGame'])this._subs.push(ctx.bus.on(event,()=>this.newGame()));},
 offer(row){
  const epoch=this.clear();
  if(this._epoch!==epoch||this._destroyed||!row?.enabled)return false;
  const choices=[],commands=new Map();
  const add=(id,label,command,title)=>{choices.push({id,label,title});commands.set(id,command);};
  let detail=prerequisiteGuidance(row);
  if(row.canAccept && !row.accepted){add('accept','HELP RESTORE THE MILE',{action:'accept',revision:row.revision});}
  else if(row.accepted && !row.abandoned){
   detail=`${row.completedMilestoneIds.length} of 5 milestones recorded. Installed: ${row.installedModuleIds.join(', ')||'none'}.`;
   if(row.crewCompletedModuleIds?.length)detail+=` Crew completed: ${row.crewCompletedModuleIds.join(', ')}. Those repairs earn no player reward.`;
   if(!row.completedMilestoneIds.includes('survey'))add('survey','SURVEY THE BREAK',{action:'survey'});
   else if(row.pendingInstall)detail+=' Installation is waiting for a clear socket.';
   else for(const [moduleId,chapterId] of [['power','recover_power'],['guide','restore_guide'],['cargo','deliver_cargo']]){
    if(row.installedModuleIds.includes(moduleId))continue;
    const repair=row.destroyedModuleIds.includes(moduleId);
    const qty=repair?2:row.cargoRequirement.qty;
    const item=repair||row.cargoRequirement.commodityId==='cmdty_scrap_metal'?'scrap metal':'food';
    let title=repair?`Use 2 scrap metal from your hold to replace the lost ${moduleId}. No second milestone reward.`:moduleId==='cargo'?`Transfer ${qty} ${item} from your hold.`:'Tow the original part into the service capture beside its matching socket at low speed. The crew seats it only when the final socket is clear.';
    const receiver = mileReceiverFeedback(row,moduleId,this.state?.tick);
    title+=' Last check: '+receiver;
    detail+=` ${moduleId[0].toUpperCase()+moduleId.slice(1)}: ${receiver}`;
    add(moduleId,repair?`REPAIR ${moduleId.toUpperCase()} (2 SCRAP)`:moduleId==='cargo'?`CONTRIBUTE ${qty} ${item.toUpperCase()}`:LABELS[moduleId],{action:'contribute',chapterId,revision:row.revision},title);
   }
   if(row.installedModuleIds.includes('power')&&!row.finalConvoyJobId&&!row.finalConvoyOutcome)add('dispatch','REQUEST THE FIRST CONVOY',{action:'dispatch'},'A real traffic hull needs a clear route and available ship budget. Stay nearby to witness its crossing.');
   if(row.finalConvoyJobId&&!row.finalConvoyOutcome)detail+=' First convoy in progress; stay near the route to witness it.';
   if(row.finalConvoyOutcome)detail+=` Convoy: ${row.finalConvoyOutcome}.`;
   if(row.finalConvoyOutcome==='arrived'&&!row.completedMilestoneIds.includes('witness_convoy'))detail+=' Witness milestone not yet recorded. No witness reward paid.';
  }else if(row.abandoned)detail='Restoration left unfinished. Existing contributions remain installed or spent.';
  if(row.lastResult?.ok===false)detail+=' '+(MILE_RECEIVER_GUIDANCE[row.lastResult.reason] || REFUSALS[row.lastResult.reason] || 'The action could not complete. Check the original part, clear socket and live tow; scan again to retry.');
  choices.push({id:'leave',label:'KEEP FLYING',cancel:true});
  const token={accepted:false},allowed=new Set(choices.map(choice=>choice.id));this._active=token;
  const accepted=getPromptDeck()?.offerDecision({id:ID,sender:'HUNDRED-HAND MILE · CREW RECORD',kind:'info',headline:'A working route, built from what survived.',detail,choices,
   onChoose:id=>{
    if(this._active!==token||!token.accepted||!allowed.has(id))return false;
    const chosenEpoch=this.clear();
    if(this._epoch!==chosenEpoch||this._destroyed)return false;
    const command=commands.get(id);if(command)this.bus.emit('hundredHandMile:command',command);
    return true;
   }})||false;
  if(this._active!==token)return false;
  if(!accepted){this.clear();return false;}
  token.accepted=true;return accepted;
 },
 clear(){const epoch=this._epoch=(this._epoch||0)+1;this._active=null;getPromptDeck()?.resolveDecision(ID);return epoch;},
 newGame(){this.clear();},
 destroy(){this._destroyed=true;this.newGame();for(const off of this._subs||[])off?.();this._subs=[];},
};

import test from 'node:test';
import assert from 'node:assert/strict';
import {fixture} from './hundred-hand-mile-finite-fixture.mjs';
import {documentAdapter} from './hundred-hand-mile-dom-adapter.mjs';
import {createPromptDeck} from '../src/ui/promptDeck.js';
import {hundredHandMilePrompt} from '../src/ui/hundredHandMilePrompt.js';
import {TALLY_THREE} from '../src/data/tallyThree.js';
import {freshTowlineTable,towlineReceiptId,towlineCleanupId} from '../src/data/towlineTable.js';
import {freshIlexArk,ILEX_ARK,ILEX_VAULT_IDS} from '../src/data/ilexArk.js';
const ID='hundred-hand-mile:restoration';
function harness(){const h=fixture(),doc=documentAdapter();h.state.mode='flight';const deck=createPromptDeck({document:doc,state:h.state,bus:h.bus}),prompt=Object.create(hundredHandMilePrompt),commands=[];prompt.init({state:h.state,bus:h.bus});h.bus.on('hundredHandMile:command',x=>commands.push(x));return {...h,doc,deck,prompt,commands,close(){prompt.destroy();deck.destroy();h.dispose()}};}
function clear(h){delete h.state.salvage.sources[TALLY_THREE.sourceKey];h.state.towlineTable=freshTowlineTable();h.state.ilexArk=freshIlexArk();delete h.state.world.lastShift;}
function snapshot(h){return JSON.stringify({graph:h.graph.serialize(),salvage:h.state.salvage,towline:h.state.towlineTable,ilex:h.state.ilexArk,world:h.state.world,cargo:h.state.player.cargo,credits:h.state.player.credits,economy:h.e.serialize()});}
function show(h,row=h.graph.readout()){const before=snapshot(h),input=JSON.stringify(row);assert.equal(h.prompt.offer(row),true);assert.equal(snapshot(h),before);assert.equal(JSON.stringify(row),input);assert.equal(h.deck.size,1);return h.doc.body.textContent;}
for(const n of [0,1,2])test(`first arrival explains ${n} of two distinct existing work families through actual graph and PromptDeck`,()=>{const h=harness();try{if(n===0)clear(h);if(n===1)h.state.towlineTable=freshTowlineTable();const row=h.graph.readout(),text=show(h,row);assert.equal(row.evidence.families.length,n);assert.match(text,new RegExp('Recorded: '+n+' of 2 kinds of work'));if(n<2){for(const name of ['Tally Three','Ilex Ark','Towline Table','Last Shift'])assert(text.includes(name));assert(!text.includes('HELP RESTORE THE MILE'));assert.match(text,/different|other|Any two/);}else assert(text.includes('HELP RESTORE THE MILE'));assert.equal(h.deck.choose(ID,'leave','test'),true);assert.deepEqual(h.commands,[]);}finally{h.close()}});
test('multiple authentic Towline receipts count as one family, not receipt IDs',()=>{const h=harness();try{delete h.state.salvage.sources[TALLY_THREE.sourceKey];for(const id of ['mara','odo'])if(h.state.towlineTable.members[id])Object.assign(h.state.towlineTable.members[id].source,{status:'cleared',receipt:{id:towlineReceiptId(id),sourceId:towlineCleanupId(id),memberId:id,stationId:'station_ceres',by:'player',at:1}});const row=h.graph.readout();assert.deepEqual(row.evidence.families,['towline']);assert.equal(row.evidence.receiptIds.length,2);row.evidence.receiptIds=['duplicate','duplicate','unrelated'];assert.match(show(h,row),/Recorded: 1 of 2 kinds of work/);}finally{h.close()}});
test('duplicate recognized readout families do not invent a second work family',()=>{const h=harness();try{const row=h.graph.readout();row.canAccept=false;row.evidence={families:['tally','tally'],receiptIds:['x','x'],eligible:false};const text=show(h,row);assert.match(text,/Recorded: 1 of 2 kinds of work/);assert.match(text,/one other|different/);assert(!text.includes('HELP RESTORE THE MILE'));}finally{h.close()}});
for(const families of [undefined,null,'tally',['tally','tethys'],['tally',{}],Array(1)])test('malformed or unknown family readout requests a fresh scan, not another job: '+JSON.stringify(families),()=>{const h=harness();try{const row=h.graph.readout();row.canAccept=false;row.evidence={families,eligible:true};const text=show(h,row);assert.match(text,/record.*refresh|record.*check/i);assert.match(text,/scan/i);assert(!/one other|two more|Complete two|Any two/.test(text));assert(!text.includes('tethys'));}finally{h.close()}});
test('eligible but distant or stale acceptance does not claim another intervention is needed',()=>{const h=harness();try{h.state.entities.get(h.state.playerId).pos.x+=1000;const row=h.graph.readout();assert.equal(row.canAccept,false);assert.equal(row.evidence.eligible,true);row.lastResult={ok:false,reason:'two-verified-interventions-required'};const text=show(h,row);assert.match(text,/Recorded: 2 of 2 kinds of work/);assert.match(text,/scan/i);assert(!/Complete two|two qualifying|one other|Any two/.test(text));}finally{h.close()}});
test('settled Ilex with no surviving vaults counts honestly without claiming delivery success',()=>{const h=harness();try{clear(h);const row=freshIlexArk();row.phase='settled';row.settlement={id:ILEX_ARK.id+':outcome',stationId:ILEX_ARK.stationId,deliveredVaultIds:[],at:10,harvestAt:10+ILEX_ARK.harvestDelayS,rewardCr:0};h.state.ilexArk=row;const readout=h.graph.readout();assert.deepEqual(readout.evidence.families,['ilex']);assert.equal(readout.evidence.survivingVaults,0);const text=show(h,readout);assert.match(text,/Recorded: 1 of 2 kinds of work/);assert.match(text,/Ilex Ark settlement/);assert(!/successful Ilex|deliver.*vault|vaults saved/i.test(text));}finally{h.close()}});
test('accepted and pending work keeps existing chapter guidance, not prerequisite errands',()=>{const h=harness();try{assert(h.graph.accept(h.graph.readout().revision).ok);let row=h.graph.readout();let text=show(h,row);assert.match(text,/0 of 5 milestones/);assert(!text.includes('kinds of work'));h.prompt.newGame();row={...row,completedMilestoneIds:['survey'],pendingInstall:{receiptId:'fixture-pending'}};text=show(h,row);assert.match(text,/Installation is waiting for a clear socket/);assert(!text.includes('Any two'));}finally{h.close()}});

test('partial Ilex settlement records its family without demanding all vaults',()=>{const h=harness();try{clear(h);const row=freshIlexArk(),id=ILEX_VAULT_IDS[0];row.phase='settled';row.vaults[id].status='delivered';row.settlement={id:ILEX_ARK.id+':outcome',stationId:ILEX_ARK.stationId,deliveredVaultIds:[id],at:10,harvestAt:10+ILEX_ARK.harvestDelayS,rewardCr:ILEX_ARK.baseRewardCr+ILEX_ARK.vaultRewardCr};h.state.ilexArk=row;const readout=h.graph.readout();assert.deepEqual(readout.evidence.families,['ilex']);assert.equal(readout.evidence.survivingVaults,1);assert.match(show(h,readout),/Recorded: 1 of 2 kinds of work: Ilex Ark settlement/);}finally{h.close()}});
test('explicit stale work order never invents a missing prerequisite task',()=>{const h=harness();try{h.state.towlineTable=freshTowlineTable();const row=h.graph.readout();row.lastResult={ok:false,reason:'stale-revision'};const text=show(h,row);assert.match(text,/refresh the work order/);assert(!text.includes('Choose one other kind of work'));}finally{h.close()}});


import {freshLastShiftRecord,LAST_SHIFT,lastShiftReport} from '../src/data/lastShift.js';
for(const n of [3,4])test('surplus '+n+' actual work kinds retain unchanged acceptance command',()=>{const h=harness();try{
 const ilex=freshIlexArk();ilex.phase='settled';ilex.settlement={id:ILEX_ARK.id+':outcome',stationId:ILEX_ARK.stationId,deliveredVaultIds:[],at:10,harvestAt:10+ILEX_ARK.harvestDelayS,rewardCr:0};h.state.ilexArk=ilex;
 if(n===4){const archive=freshLastShiftRecord();archive.knownClueIds=['fairlead'];archive.receipts=[{id:LAST_SHIFT.siteId+':archive:r1',revision:1,at:10,clueIds:['fairlead'],destroyedClueIds:[],text:lastShiftReport(['fairlead'],[])}];h.state.world.lastShift=archive;}
 const row=h.graph.readout();assert.equal(row.evidence.families.length,n);assert.equal(row.evidence.eligible,true);assert.equal(row.canAccept,true);
 const text=show(h,row);assert(text.includes('Recorded: '+n+' kinds of work (2 required)'));assert(!/Choose one other|Any two count| of 2 kinds/.test(text));assert(text.includes('HELP RESTORE THE MILE'));
 assert.equal(h.deck.choose(ID,'accept','test'),true);assert.deepEqual(h.commands,[{action:'accept',revision:row.revision}]);
}finally{h.close()}});

test('missing Ceres work guidance names the physical Tally delivery and partial Last Shift filing',()=>{const h=harness();try{clear(h);const text=show(h);assert.match(text,/Ceres: tow Tally Three.s original crate on your live Massline to Ceres Refinery; slow the crate to 8 WU\/s or less, hail and choose DELIVER/);assert.match(text,/Ceres: select a marked Last Shift wreck, pulse scan within 320 WU, then choose FILE 1\/3 SOURCES; a partial report counts/);assert.equal(h.commands.length,0);}finally{h.close()}});
test('earned Tally family no longer asks for its physical delivery',()=>{const h=harness();try{h.state.towlineTable=freshTowlineTable();const text=show(h);assert.match(text,/Tally Three delivery/);assert(!text.includes('tow Tally Three'));assert.match(text,/select a marked Last Shift wreck/);}finally{h.close()}});
test('earned Last Shift family no longer asks for another archive report',()=>{const h=harness();try{clear(h);const archive=freshLastShiftRecord();archive.knownClueIds=['fairlead'];archive.revision=1;archive.receipts=[{id:LAST_SHIFT.siteId+':archive:r1',revision:1,at:10,clueIds:['fairlead'],destroyedClueIds:[],text:lastShiftReport(['fairlead'],[])}];h.state.world.lastShift=archive;const text=show(h);assert.match(text,/Last Shift archive report/);assert(!text.includes('select a marked Last Shift wreck'));assert.match(text,/tow Tally Three/);}finally{h.close()}});

function captureMileOffer(h){const original=h.deck.offerDecision;let latest;h.deck.offerDecision=spec=>{latest=spec;return original(spec);};return {get latest(){return latest;},restore(){h.deck.offerDecision=original;}};}
test('Mile retained callback is current, rendered-choice-only and once-only',()=>{const h=harness(),capture=captureMileOffer(h);try{h.prompt.offer(h.graph.readout());const cb=capture.latest.onChoose;assert.equal(cb('dispatch'),false);assert.equal(h.commands.length,0);assert.equal(cb('accept'),true);assert.equal(cb('accept'),false);assert.equal(h.commands.length,1);}finally{capture.restore();h.close()}});
test('Mile replacement leaves only the newer callback callable',()=>{const h=harness(),capture=captureMileOffer(h);try{const row=h.graph.readout();h.prompt.offer(row);const old=capture.latest.onChoose;h.prompt.offer({...row,revision:row.revision+1});assert.equal(old('accept'),false);assert.equal(h.commands.length,0);assert.equal(capture.latest.onChoose('accept'),true);assert.deepEqual(h.commands,[{action:'accept',revision:row.revision+1}]);}finally{capture.restore();h.close()}});
for(const replacement of [null,{enabled:false}])test('Mile unusable readout retires retained authority: '+JSON.stringify(replacement),()=>{const h=harness(),capture=captureMileOffer(h);try{h.prompt.offer(h.graph.readout());const cb=capture.latest.onChoose;assert.equal(h.prompt.offer(replacement),false);assert.equal(cb('accept'),false);assert.equal(h.commands.length,0);}finally{capture.restore();h.close()}});
test('Mile rejected and not-yet-accepted offers never authorize a callback',()=>{const h=harness(),original=h.deck.offerDecision;let cb;try{h.deck.offerDecision=spec=>{cb=spec.onChoose;assert.equal(cb('accept'),false);return false;};assert.equal(h.prompt.offer(h.graph.readout()),false);assert.equal(cb('accept'),false);assert.equal(h.commands.length,0);}finally{h.deck.offerDecision=original;h.close()}});
for(const event of ['sector:exit','dock:completed','dock:docked','save:restoring','save:loaded','game:load','game:new','game:newGame'])test('Mile lifecycle retires retained choice: '+event,()=>{const h=harness(),capture=captureMileOffer(h);try{h.prompt.offer(h.graph.readout());const cb=capture.latest.onChoose;h.bus.emit(event,{});assert.equal(cb('accept'),false);assert.equal(h.commands.length,0);}finally{capture.restore();h.close()}});
test('Mile leave consumes the rendered callback without sending a command',()=>{const h=harness(),capture=captureMileOffer(h);try{h.prompt.offer(h.graph.readout());const cb=capture.latest.onChoose;assert.equal(cb('leave'),true);assert.equal(cb('accept'),false);assert.equal(h.commands.length,0);}finally{capture.restore();h.close()}});
test('Mile resolution reentry replaces the card and cancels the old command',()=>{const h=harness(),capture=captureMileOffer(h),resolve=h.deck.resolveDecision;try{const row=h.graph.readout();h.prompt.offer(row);const cb=capture.latest.onChoose;let once=false;h.deck.resolveDecision=id=>{const result=resolve(id);if(!once){once=true;h.prompt.offer({...row,revision:row.revision+1});}return result;};assert.equal(cb('accept'),false);assert.equal(h.commands.length,0);assert.equal(capture.latest.onChoose('accept'),true);assert.deepEqual(h.commands,[{action:'accept',revision:row.revision+1}]);}finally{h.deck.resolveDecision=resolve;capture.restore();h.close()}});
test('Mile lifecycle during resolution cancels the selected command',()=>{const h=harness(),capture=captureMileOffer(h),resolve=h.deck.resolveDecision;try{h.prompt.offer(h.graph.readout());const cb=capture.latest.onChoose;let once=false;h.deck.resolveDecision=id=>{const result=resolve(id);if(!once){once=true;h.bus.emit('save:restoring',{});}return result;};assert.equal(cb('accept'),false);assert.equal(h.commands.length,0);}finally{h.deck.resolveDecision=resolve;capture.restore();h.close()}});
test('Mile emission reentry keeps a fresh offer live',()=>{const h=harness(),capture=captureMileOffer(h);let off;try{const row=h.graph.readout();h.prompt.offer(row);const cb=capture.latest.onChoose;let once=false;off=h.bus.on('hundredHandMile:command',()=>{if(!once){once=true;h.prompt.offer({...row,revision:row.revision+1});}});assert.equal(cb('accept'),true);assert.equal(capture.latest.onChoose('accept'),true);assert.deepEqual(h.commands,[{action:'accept',revision:row.revision},{action:'accept',revision:row.revision+1}]);}finally{off?.();capture.restore();h.close()}});

